import numpy as np
from scipy.optimize import least_squares
forms={
 'exp':lambda t,k:1-np.exp(-k*t),
 'tanh':lambda t,k:np.tanh(k*t),
 'sat':lambda t,k:t/(t+k),
 'log':lambda t,k:np.log(1+k*t),
 'sqrt':lambda t,k:np.sqrt(1+k*t)-1,
 'atan':lambda t,k:np.arctan(k*t),
 'exp2':lambda t,k:1-np.exp(-k*t*t),
 'sat2':lambda t,k:t*t/(t*t+k),
}
def rest_basis(S):
    return [np.ones_like(t),P,P**2,P**3,P*t,P**2*t,P*S]
out=[]
for name,f in forms.items():
    def resid(p):
        S=p[0]*f(t,p[1])
        A=np.array(rest_basis(S)+[S]).T
        c,_,_,_=np.linalg.lstsq(A,dP_dt,rcond=None)
        return dP_dt-A@c
    best=None
    for k0 in [0.1,0.3,1,3]:
        for a0 in [5,15]:
            try:
                r=least_squares(resid,[a0,k0])
                v=np.mean(r.fun**2)/np.var(dP_dt)
                if best is None or v<best[0]: best=(v,r.x)
            except Exception as e: pass
    out.append((name,best))
for o in out: print(o)

